with open('outputs/t09_poi_nearest_stop.csv', 'r', encoding='utf-8') as f:
    reader = csv.reader(f)
    for i, row in enumerate(reader):
        if i == 0:
            print(f'Header: {len(row)} fields: {row}')
        else:
            if len(row) != 6:
                print(f'Row {i}: Expected 6 fields, got {len(row)}: {row}')
