            for j, field in enumerate(row):
                if ',' in field and '\"' not in field:
                    print(f'Row {i}, field {j} has unquoted comma: {repr(field)}')
                if '\"' in field and '\"\"' not in field:
                    print(f'Row {i}, field {j} has unquoted quote: {repr(field)}')
print('RFC 4180 check complete')
