import csv
with open('outputs/t09_poi_nearest_stop.csv', 'r', encoding='utf-8') as f:
    content = f.read()
    # Parse the CSV properly
    reader = csv.reader(content.splitlines())
    for i, row in enumerate(reader):
        if i == 0:
            print(f'Header: {len(row)} fields')
            continue
        # Check if the row has exactly 6 fields
        if len(row) != 6:
            print(f'ERROR: Row {i} has {len(row)} fields instead of 6')
        # Check if fields with commas are quoted
        for j, field in enumerate(row):
            if ',' in field and '\"' not in field:
                print(f'ERROR: Row {i}, field {j} has unquoted comma: {repr(field)}')
print('Check complete')
